<template>
  <div class="language-pop">
    <div class="title">选择语言
      <svg-icon icon-class="抽屉_close" :width="24" :height="24" @click="closeLanguage" />
    </div>
    <div class="language-list">
      <div v-for="(item, index) in languageList" :key="index" :class="currentLanguage===item.value?'language-selected language-item':'language-item'" @click="changeLanguage(item.value)">
        <svg-icon :icon-class="item.svgIcon" :width="20" :height="20" />
        <div class="language-name">{{ item.label }}</div>
        <div v-if="currentLanguage===item.value" class="select-icon" />
      </div>
    </div>
  </div>
</template>
<script>
import { setlang } from '@/api/user'
export default {
  data() {
    return {
      currentLanguage: 'cn',
      languageList: [
        { value: 'cn', label: '中文[简体]', svgIcon: '中国' },
        // { value: 'zh-CN1', label: '中文[繁体]', svgIcon: '中国' },
        { value: 'en', label: 'English', svgIcon: '英国' },
        { value: 'yn', label: 'Tiếng Việt', svgIcon: '越南' },
        // { value: 'en-ko', label: '한국인', svgIcon: '韩国' },
        // { value: 'ja-JP', label: '日本語', svgIcon: '日本' }
      ]
    }
  },
  async created() {
    this.currentLanguage = localStorage.lang || 'cn'
  },
  methods: {
    async changeLanguage(language) {
      this.currentLanguage = language
      localStorage.setItem('lang', language)
      this.$i18n.locale = language
      await setlang({lang:language})
      location.reload()
      // this.$emit('close')
    },
    closeLanguage() {
      this.$emit('close')
    }
  }
}
</script>
<style lang="less" >
.language-pop{
    height: 1106px;
    width: 100vw;
    padding-bottom: 50px;
    background: #1D1C29;
    border-radius: 32px 32px 0 0;
    // margin-top: 180px;
    // background: url('~@/assets/portal/bg_内页普通背景.png') no-repeat 50%;
    // background-size: 100% 100%;
    .title{
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-family: PingFangSC-Semibold;
      font-size: 32px;
      color: #FFFFFF;
      text-align: center;
      line-height: 48px;
      font-weight: 600;
      padding: 32px;
    }
    .language-list{
      padding: 0 32px;
      .language-item {
        display: flex;
        align-items: center;
        height:80px;
        font-family: PingFangSC-Regular;
        font-size: 28px;
        color: #FFFFFF;
        font-weight: 400;
        padding: 0 24px;
        // box-shadow: inset 0 -2px 0 0 rgba(255,255,255,0.12);
        .language-name {
          margin-left: 24px;
        }
        .select-icon {
          background: url('~@/assets/portal/复选框_s.png');
          background-size: 100% 100%;
          margin-left: auto;
          height: 32px;
          width: 32px;
        }
      }
      .language-selected {
        background: rgba(255,255,255,0.10);
        border-radius: 8px;
      }
    }
}
.van-popup {
    overflow-y: initial;
    background-color: transparent;
}
</style>
