import Vue from 'vue'
import { mapGetters } from 'vuex'
import VueClipboard from 'vue-clipboard2'

import CustomerService from '../../portal/modules/CustomerService.vue'
Vue.use(VueClipboard)

export default {
  components: {
    CustomerService
  },
  props: {
    isDetail: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      showService: false
    }
  },
  computed: {
    ...mapGetters(['userInfo'])
  },
  methods: {
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success('ID' + this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    },
    toUserSetting() {
      this.$router.push({ name: 'UserSetting' })
    }
  }
}
</script>

