<script>
import LanguageList from '@/views/portal/modules/Language'
import { getInfo } from '@/api/user'
export default {
  components: {
    LanguageList
  },
  data() {
    return {
      showLanguageList: false,
      showOld: true,
      content: '',
      language: ''
    }
  },
  mounted() {
    const dom = document.getElementsByClassName('van-tabbar-item__text')[0]
    if (dom.innerText === '首页') {
      this.showOld = false
    } else {
      this.showOld = true
    }
    getInfo().then(res => {
      this.content = res.chiptypename
      this.language = localStorage.getItem('lang') === 'cn' ? '简体中文' :localStorage.getItem('lang') === 'yn' ? 'Tiếng Việt' : 'English'
    }).catch(err=>{
       console.error('接口报错:', err.message);
    })
    this.$store.dispatch('user/getInfo')
  },
  methods: {
    returnOld(type) {
      if (type === 'old') {
        localStorage.setItem('lang', 'cn')
        this.$i18n.locale = 'cn'
        this.$router.push('/oldhome')
      } else {
        this.$router.push('/home')
      }
    },
    logout() {
      this.$store.dispatch('user/logout')
        .then(() => {
          // this.$notify({
          //   type: 'success',
          //   message: '退出成功',
          //   duration: 2000,
          //   onOpened: () => {
          //     // this.$router.push({ name: 'Login' })
          //     // this.$router.push({ path: '/home', query: { suid: '' }})

          //   }
          // })
          this.$toast(this.$t('login.dlym13'))
          setTimeout(() => {
            if (this.showOld) {
              this.$router.push({ path: '/home' })
            } else {
              this.$router.push({ path: '/oldhome' })
            }
          }, 2000)
          // window.open(window.location.origin + '/#/home?suid=', '_self')
        })
    }
  }
}
</script>

