<template>
  <div class="invite">
    <div class="first-line">
      <div class="title">{{ $t('mywd.wd20') }}{{ backs }}  {{ $t('mywd.wd21') }}</div>
      <div class="detail" @click="$router.push('/shareFriends')">{{ $t('mywd.wd22') }} ></div>
    </div>
    <div class="tel_url">
      <div class="text">{{ inviteUrl }}</div>
      <div class="copy-icon" @click="doCopy(inviteUrl)">{{ $t('mywd.wd23') }}</div>
    </div>
    <!-- <div class="invite-span">
      <div class="invite-url" />
      <div class="copy-btn" @click="doCopy(inviteUrl)" />
    </div> -->
  </div>
</template>
<script>
import Vue from 'vue'
import { mapGetters } from 'vuex'
import VueClipboard from 'vue-clipboard2'
Vue.use(VueClipboard)
import { shareother } from '@/api/user'
export default {
  components: {
  },
  data() {
    return {
      inviteUrl: '',
      backs: ''
    }
  },
  computed: {
    ...mapGetters(['userInfo'])
  },
  created() {
    shareother().then(async res => {
      this.backs = res.maxdownback
      this.inviteUrl = res.telurl
    })
  },
  methods: {

    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success('ID' + this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }
  }
}
</script>
<style lang="less" scoped>
.invite{
  height: 160px;
  margin: 24px 28px;
  background: var(--invite-bg);
  background-size: cover;
  display: flex;
  flex-direction: column;
  .first-line{
    display: flex;
    margin: 16px 20px 8px 144px;
    justify-content: space-between;
    .title{
      font-family: PingFangSC-Medium;
      font-size: 24px;
      color: #FFFFFF;
      line-height: 40px;
      font-weight: 500;
    }
    .detail{
      font-family: PingFangSC-Regular;
      font-size: 24px;
      color: var(--text-color-secondary);
      text-align: right;
      line-height: 40px;
      font-weight: 400;
    }
  }
  .tel_url{
      margin: 0px 20px 16px 144px;
      background: rgba(0,0,0,0.30);
      border-radius: 12px;
      height: 80px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 0 0px 0 24px;
      font-family: PingFangSC-Medium;
      font-size: 24px;
      color: #FFFFFF;
      line-height: 20px;
      font-weight: 500;
    }
    .text{
      font-family: PingFangSC-Medium;
              font-size: 24px;
              color: #FFFFFF;
              font-weight: 500;
              // padding-left: 24px;
              line-height: 80px;
              width: 462px;
              white-space: nowrap;
              overflow: hidden;
              text-overflow: ellipsis;
    }
    .copy-icon{
              background-image: var(--btn-bg-color-share);
              border-radius: 8px;
                width: 120px;
                line-height: 56px;
                height: 56px;
                text-align: center;
                font-family: PingFangSC-Semibold;
                font-size: 24px;
                color: var(--btn-text-color);
                font-weight: 600;
                margin: 12px;

    }
}
</style>
